static std::vector<uint8_t> rleDecode (const unsigned char* d, size_t n, size_t rawSize)
{
    std::vector<uint8_t> out;
    out.reserve (rawSize);
    for (size_t i = 0; i < n; )
    {
        const uint8_t count = d[i++];
        if (count == 0)                       // run: 00 <length> <value>
        {
            const uint8_t len = d[i];
            const uint8_t val = d[i + 1];
            i += 2;
            out.insert (out.end(), len, val);
        }
        else                                  // literal: <length> <bytes...>
        {
            out.insert (out.end(), d + i, d + i + count);
            i += count;
        }
    }
    return out;
}

std::vector<uint8_t> blankData (const std::string& kind, int version)
{
    for (size_t i = 0; i < blankdata::entryCount; ++i)
    {
        const auto& e = blankdata::entries[i];
        if (kind == e.kind && e.version == version)
        {
            auto out = rleDecode (e.data, e.encodedSize, e.rawSize);
            if (out.size() != e.rawSize)
                throw DigitaktError ("blank data for " + kind + " v"
                                     + std::to_string (version) + " is corrupt");
            return out;
        }
    }
    throw DigitaktError ("no blank " + kind + " for storage version "
                         + std::to_string (version));
}

std::vector<int> blankVersions (const std::string& kind)
{
    std::vector<int> out;
    for (size_t i = 0; i < blankdata::entryCount; ++i)
        if (kind == blankdata::entries[i].kind)
            out.push_back (blankdata::entries[i].version);
    return out;
}

